#include <stdio.h>
#include <string.h>

void reverse(char s[]) {
    int n = strlen(s);
    for (int i = 0; i < n / 2; i++) {
        char temp = s[i];
        s[i] = s[n - 1 - i];
        s[n - 1 - i] = temp;
    }
}

int main() {
    char word[] = "hello";
    reverse(word);
    printf("%s\n", word);
    return 0;
}
